// Tests for the ALPH (alpha plane of lossy WebP) support of WebPDecoderGpu and WebPLosslessEncoderGpu.
//
// Fixtures (TestData/WebP/alph_*, generated by scripts/images/make_webp_alpha_fixtures.py): VP8X files holding a small
// lossy VP8 image plus an ALPH chunk. Two families: ALPH chunks crafted from an independent numpy implementation of the
// four prediction filters (none / horizontal / vertical / gradient), stored raw or compressed by libwebp's own VP8L
// encoder (every VP8L transform, colour cache, palette bundling inside the headerless stream), and ALPH chunks written by
// libwebp's lossy encoder itself (alpha_quality 100 and a reduced one that sets the pre-processing field). The truth
// plane (.alpha8.gz) is what libwebp decodes (the generator asserts it equals the source plane where the chunk is
// lossless). The animation fixture has three lossy frames with their own ALPH chunks.
//
// What can fail: every fixture through the managed and the ArrayView1D overload (into a poisoned, over-long buffer whose
// tail must stay untouched), every animation frame, and the error paths (invalid header bits, truncated raw data, an
// image without ALPH, a cut VP8L stream) which must throw ImageDecodeException with the specific reason.

using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.WebP;
using SpawnDev.ILGPU;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private sealed record WebPAlphaFixtureRow(
        string Name, string Kind, int Width, int Height, int Frames, int Method, int Filter, int Preprocessing, string Features);

    private static List<WebPAlphaFixtureRow> WebPAlphaManifest()
    {
        var text = System.Text.Encoding.UTF8.GetString(ReadEmbedded(WebPFixturePrefix + "alph_manifest.tsv"));
        var rows = new List<WebPAlphaFixtureRow>();
        foreach (var raw in text.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            if (line.Length == 0) continue;
            var c = line.Split('\t');
            rows.Add(new WebPAlphaFixtureRow(c[0], c[1], int.Parse(c[2]), int.Parse(c[3]), int.Parse(c[4]),
                int.Parse(c[5]), int.Parse(c[6]), int.Parse(c[7]), c[8]));
        }
        if (rows.Count == 0) throw new InvalidOperationException("The ALPH manifest is empty.");
        return rows;
    }

    private static byte[] WebPAlphaTruth(string name) => Gunzip(ReadEmbedded(WebPFixturePrefix + name + ".alpha8.gz"));

    private static byte[] WebPAlphaFrameTruth(string name, int k) => Gunzip(ReadEmbedded(WebPFixturePrefix + name + ".f" + k + ".alpha8.gz"));

    /// <summary>The top-level RIFF chunks of a WebP file (fourcc, payload without padding).</summary>
    private static List<(string Fcc, byte[] Payload)> WebPChunksOf(byte[] file)
    {
        var chunks = new List<(string, byte[])>();
        int pos = 12;
        while (pos + 8 <= file.Length)
        {
            string fcc = System.Text.Encoding.ASCII.GetString(file, pos, 4);
            int size = BitConverter.ToInt32(file, pos + 4);
            chunks.Add((fcc, file.AsSpan(pos + 8, size).ToArray()));
            pos += 8 + size + (size & 1);
        }
        return chunks;
    }

    /// <summary>A RIFF/WEBP file from chunks (padding and the RIFF size are computed).</summary>
    private static byte[] WebPAssemble(IEnumerable<(string Fcc, byte[] Payload)> chunks)
    {
        using var ms = new MemoryStream();
        ms.Write("RIFF\0\0\0\0WEBP"u8);
        foreach (var (fcc, payload) in chunks)
        {
            ms.Write(System.Text.Encoding.ASCII.GetBytes(fcc));
            ms.Write(BitConverter.GetBytes(payload.Length));
            ms.Write(payload);
            if ((payload.Length & 1) == 1) ms.WriteByte(0);
        }
        var bytes = ms.ToArray();
        BitConverter.GetBytes(bytes.Length - 8).CopyTo(bytes, 4);
        return bytes;
    }

    /// <summary>The same file with the payload of the first chunk called <paramref name="fcc"/> replaced.</summary>
    private static byte[] WebPWithChunk(byte[] file, string fcc, byte[] payload)
    {
        var chunks = WebPChunksOf(file);
        int i = chunks.FindIndex(c => c.Fcc == fcc);
        if (i < 0) throw new InvalidOperationException("no " + fcc + " chunk");
        chunks[i] = (fcc, payload);
        return WebPAssemble(chunks);
    }

    private static byte[] WebPChunkPayload(byte[] file, string fcc) => WebPChunksOf(file).First(c => c.Fcc == fcc).Payload;

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_Alpha_AllFixtures_MatchLibwebp_ManagedAndArrayView()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            var methods = new HashSet<int>();
            var filters = new HashSet<int>();
            foreach (var row in WebPAlphaManifest().Where(r => r.Kind == "still"))
            {
                try
                {
                    byte[] file = ReadEmbedded(WebPFixturePrefix + row.Name + ".webp");
                    byte[] truth = WebPAlphaTruth(row.Name);
                    var managed = await dec.DecodeAlphaAsync(file);
                    if (managed.Width != row.Width || managed.Height != row.Height)
                        failures.Add($"{row.Name}: plane size {managed.Width}x{managed.Height}, expected {row.Width}x{row.Height}");
                    var diff = ComparePixels(truth, managed.Alpha, 1, row.Width);
                    if (diff != null) failures.Add($"{row.Name} [managed] (method {row.Method}, filter {row.Filter}): {diff}");

                    using var dFile = acc.Allocate1D<byte>(file.Length + 9);
                    DeviceTransfer.Upload(dFile.View, file);
                    using var dOut = acc.Allocate1D<byte>(truth.Length + 13);
                    DeviceTransfer.Upload(dOut.View, Poison((int)dOut.Length));
                    var frame = await dec.DecodeAlphaAsync(dFile.View, file.Length, dOut.View);
                    var viewPlane = await DeviceTransfer.DownloadAsync(dOut.View, truth.Length);
                    diff = ComparePixels(truth, viewPlane, 1, row.Width);
                    if (diff != null) failures.Add($"{row.Name} [ArrayView1D]: {diff}");
                    if (frame.Width != row.Width || frame.Height != row.Height)
                        failures.Add($"{row.Name}: frame size {frame.Width}x{frame.Height}");
                    var tail = await dOut.View.SubView(truth.Length, 13).CopyToHostAsync();
                    if (tail.Any(b => b != 0xAB)) failures.Add($"{row.Name}: bytes past the plane were written");

                    // the colour image is not decodable yet, but the facts must say the file carries alpha
                    var info = await dec.ReadInfoAsync(file);
                    if (!info.HasAlpha) failures.Add($"{row.Name}: ReadInfo says no alpha");
                    methods.Add(row.Method);
                    filters.Add(row.Filter);
                    count++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{row.Name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(count > 60, $"only {count} ALPH fixtures were exercised");
            True(methods.SetEquals(new[] { 0, 1 }) && filters.SetEquals(new[] { 0, 1, 2, 3 }),
                "the fixture set must cover both compression methods and all four filters");
            True(failures.Count == 0, $"{failures.Count} ALPH fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task WebPDecoderGpu_Alpha_AnimationFrames_EachFrameHasItsOwnPlane()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            string name = "alph_anim_48x40";
            byte[] file = ReadEmbedded(WebPFixturePrefix + name + ".webp");
            var frames = await dec.ReadFramesAsync(file);
            Equal(3, frames.Length, "frame count");
            for (int k = 0; k < frames.Length; k++)
            {
                var truth = WebPAlphaFrameTruth(name, k);
                var plane = await dec.DecodeAlphaAsync(file, k);
                Equal(frames[k].Width, plane.Width, $"frame {k} width");
                Equal(frames[k].Height, plane.Height, $"frame {k} height");
                Equal(null, ComparePixels(truth, plane.Alpha, 1, plane.Width), $"frame {k}");
            }
            // the three planes differ, so a decoder that ignored frameIndex could not pass
            True(frames[0].Width != frames[1].Width && frames[1].Height != frames[2].Height, "frames differ in size");

            bool threw = false;
            try { await dec.DecodeAlphaAsync(file, 3); }
            catch (ArgumentOutOfRangeException) { threw = true; }
            True(threw, "frame index 3 of 3");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    private async Task AssertAlphaRejectedAsync(byte[] file, string expectedMessagePart, string what)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            ImageDecodeException? caught = null;
            try { await dec.DecodeAlphaAsync(file); }
            catch (ImageDecodeException ex) { caught = ex; }
            NotNull(caught, $"{what}: expected ImageDecodeException");
            Contains(expectedMessagePart, caught!.Message, what);
            Equal(ImageFormat.WebP, caught.Format, what + " format");
            // the decoder must still work afterwards
            var good = ReadEmbedded(WebPFixturePrefix + "alph_smooth_64x48_f0_raw.webp");
            var ok = await dec.DecodeAlphaAsync(good);
            Equal(null, ComparePixels(WebPAlphaTruth("alph_smooth_64x48_f0_raw"), ok.Alpha, 1, 64), what + ": decoder usable after the error");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_Alpha_InvalidHeaders_AreRejected_LikeLibwebp()
    {
        // libwebp rejects each of these (the fixture generator asserts it, section 4): compression method 2 and 3,
        // pre-processing 2, any reserved bit, an empty chunk, a header byte alone.
        var raw = ReadEmbedded(WebPFixturePrefix + "alph_smooth_64x48_f0_raw.webp");
        var alph = WebPChunkPayload(raw, "ALPH");
        Equal(0, alph[0], "baseline header byte");
        foreach (var (hdr, what) in new[] { ((byte)2, "method 2"), ((byte)3, "method 3"), ((byte)0x20, "pre-processing 2"),
                     ((byte)0x40, "reserved bit 6"), ((byte)0x80, "reserved bit 7") })
        {
            var bad = (byte[])alph.Clone();
            bad[0] = hdr;
            await AssertAlphaRejectedAsync(WebPWithChunk(raw, "ALPH", bad), "invalid ALPH", what);
        }
        await AssertAlphaRejectedAsync(WebPWithChunk(raw, "ALPH", System.Array.Empty<byte>()), "invalid ALPH", "empty ALPH chunk");
        await AssertAlphaRejectedAsync(WebPWithChunk(raw, "ALPH", new byte[] { 0 }), "invalid ALPH", "header byte only");
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_Alpha_TruncatedData_IsRejected()
    {
        var raw = ReadEmbedded(WebPFixturePrefix + "alph_smooth_64x48_f0_raw.webp");
        var alph = WebPChunkPayload(raw, "ALPH");
        await AssertAlphaRejectedAsync(WebPWithChunk(raw, "ALPH", alph.AsSpan(0, alph.Length - 1).ToArray()),
            "fewer bytes than the plane", "raw plane one byte short");

        var vp8l = ReadEmbedded(WebPFixturePrefix + "alph_smooth_64x48_f3_vp8l.webp");
        var comp = WebPChunkPayload(vp8l, "ALPH");
        await AssertAlphaRejectedAsync(WebPWithChunk(vp8l, "ALPH", comp.AsSpan(0, comp.Length / 2).ToArray()),
            "truncated", "VP8L alpha stream cut in half");
        await AssertAlphaRejectedAsync(WebPWithChunk(vp8l, "ALPH", comp.AsSpan(0, 2).ToArray()),
            "truncated", "VP8L alpha stream cut after 1 byte");
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_Alpha_ImageWithoutAlphChunk_IsRejected()
    {
        await AssertAlphaRejectedAsync(WebPFile("flat_32x24"), "no ALPH chunk", "lossless image");
        await AssertAlphaRejectedAsync(WebPFile("lossy_rgb_32x32"), "no ALPH chunk", "lossy RGB image");
        // an ALPH chunk AFTER the VP8 chunk belongs to nothing (libwebp ignores it)
        var good = ReadEmbedded(WebPFixturePrefix + "alph_smooth_64x48_f0_raw.webp");
        var chunks = WebPChunksOf(good);
        var reordered = new List<(string, byte[])> { chunks[0], chunks[2], chunks[1] };
        await AssertAlphaRejectedAsync(WebPAssemble(reordered), "no ALPH chunk", "ALPH after VP8");
    }

    [TestMethod]
    public async Task WebPDecoderGpu_Alpha_BufferTooSmall_Throws()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var file = ReadEmbedded(WebPFixturePrefix + "alph_smooth_64x48_f0_raw.webp");
            using var dFile = acc.Allocate1D<byte>(file.Length);
            DeviceTransfer.Upload(dFile.View, file);
            using var dOut = acc.Allocate1D<byte>(64 * 48 - 1);
            bool threw = false;
            try { await dec.DecodeAlphaAsync(dFile.View, file.Length, dOut.View); }
            catch (ArgumentException) { threw = true; }
            True(threw, "output one byte short");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }
}
